const fs = require('fs');
const path = require('path');

const configPath = path.join(__dirname, 'config.json');
const outPath = path.join(__dirname, 'config.out.json');

const config = JSON.parse(fs.readFileSync(configPath, 'utf8'));

const result = {
  port: config.port !== undefined ? config.port : 3000,
  host: config.host !== undefined ? config.host : '127.0.0.1',
  ...config,
};

result.port = result.port !== undefined ? result.port : 3000;
result.host = result.host !== undefined ? result.host : '127.0.0.1';

fs.writeFileSync(outPath, JSON.stringify(result, null, 2) + '\n');
console.log('wrote', outPath);

